  const STRATEGY_PARAM_META = {
    execution_mode: { label: 'Execution Mode' },
    max_size_usdc: { label: 'Max Size (USDC)', type: 'number', min: 1, step: 1, format: (v) => fmt.usd(v) },
    max_positions: { label: 'Max Positions', type: 'number', min: 1, step: 1 },
    min_signal_tier: { label: 'Min Signal Tier' },
    min_score: { label: 'Min Score', type: 'number', min: 0, max: 100, step: 1 },
    min_position_value_usdc: { label: 'Min Source Position Value', type: 'number', min: 0, step: 1, format: (v) => fmt.usd(v) },
    min_source_notional_usdc: { label: 'Min Source Notional', type: 'number', min: 0, step: 1, format: (v) => fmt.usd(v) },
    bet_size_usdc: { label: 'Bet Size (USDC)', type: 'number', min: 1, step: 1, format: (v) => fmt.usd(v) },
    max_concurrent_positions: { label: 'Max Concurrent Positions', type: 'number', min: 1, step: 1 },
    max_entry_price: { label: 'Max Entry Price', type: 'number', min: 0, max: 1, step: 0.01, format: (v) => fmt.price(v) },
    max_days_to_resolution: { label: 'Max Days To Resolution', type: 'number', min: 1, step: 1 },
    stale_days: { label: 'Stale Days', type: 'number', min: 1, step: 1 },
    resolution_win_threshold: { label: 'Resolution Win Threshold', type: 'number', min: 0, max: 1, step: 0.01, format: (v) => fmt.price(v) },
    resolution_loss_threshold: { label: 'Resolution Loss Threshold', type: 'number', min: 0, max: 1, step: 0.01, format: (v) => fmt.price(v) },
    max_exposure_per_market_usdc: { label: 'Max Exposure / Market', type: 'number', min: 0, step: 1, format: (v) => fmt.usd(v) },
    fade_threshold: { label: 'Fade Threshold', type: 'number', min: 0, max: 1, step: 0.01 },
    min_insider_score: { label: 'Min Insider Score', type: 'number', min: 0, max: 100, step: 1, offValue: 'off' },
    max_adverse_drift_pct: { label: 'Max Adverse Drift %', type: 'number', min: 0, max: 1, step: 0.01, format: (v) => `${(Number(v) * 100).toFixed(0)}%`, offValue: 'off', placeholder: 'off' },
    max_favorable_drift_pct: { label: 'Max Favorable Drift %', type: 'number', min: 0, max: 1, step: 0.01, format: (v) => `${(Number(v) * 100).toFixed(0)}%`, offValue: 'off', placeholder: 'off' },
  };

  function buildStrategyParamEntries(type, params = {}) {
    const defaults = (STRATEGY_TEMPLATES[type] && STRATEGY_TEMPLATES[type].defaults) || {};
    const merged = { ...defaults };
    Object.entries(params || {}).forEach(([k, v]) => { merged[k] = v; });
    return Object.entries(merged);
  }

  function formatStrategyParamValue(key, value) {
    const meta = STRATEGY_PARAM_META[key] || {};
    if (value === '' || value == null) return meta.offValue || '—';
    if (key === 'min_insider_score' && Number(value) === 0) return meta.offValue || 'off';
    if ((key === 'max_adverse_drift_pct' || key === 'max_favorable_drift_pct') && value !== '' && value != null) {
      return meta.format ? meta.format(value) : `${value}`;
    }
    return meta.format ? meta.format(value) : String(value);
  }

  function renderStrategyParamFields(type, params = {}) {
    return buildStrategyParamEntries(type, params).map(([k, v]) => {
      const meta = STRATEGY_PARAM_META[k] || {};
      const inputType = meta.type || 'text';
      const attrs = [
        `type="${inputType}"`,
        `class="strat-param"`,
        `data-key="${esc(k)}"`,
        `value="${esc(v === '' || v == null ? '' : String(v))}"`,
      ];
      if (meta.min !== undefined) attrs.push(`min="${meta.min}"`);
      if (meta.max !== undefined) attrs.push(`max="${meta.max}"`);
      if (meta.step !== undefined) attrs.push(`step="${meta.step}"`);
      if (meta.placeholder) attrs.push(`placeholder="${meta.placeholder}"`);
      return `
        <div class="strat-form-group">
          <label>${esc(meta.label || k)}</label>
          <input ${attrs.join(' ')} />
        </div>
      `;
    }).join('');
  }

